import json, subprocess, collections, re
def q(sql):
    out = subprocess.run(["psql","-d","aistudio","-At","-F","\x1f","-c",sql],capture_output=True,text=True,check=True).stdout
    return [l.split("\x1f") for l in out.splitlines() if l]
tasks = q("select t.id,t.run_name,t.status,t.task_config::text,n.machine_id,t.started_at from tasks t left join nodes n on n.id=t.node_id order by t.started_at, t.run_name")
logs = collections.defaultdict(list)
for tid,line in q("select task_id,line from task_logs order by task_id,logged_at"): logs[tid].append(line)
cols="run_id,sub_run_index,model_name,pipeline_version,gpu_type,gpu_count,precision,input_tokens,output_tokens,concurrency,parallelism,status,total_token_throughput,duration_seconds,metrics".split(",")
res=collections.defaultdict(list)
for r in q("select "+",".join(f"coalesce({c}::text,'')" for c in cols)+" from benchmark_results order by run_id,sub_run_index"):
    d=dict(zip(cols,r)); d["metrics"]=json.loads(d["metrics"]); res[d["run_id"]].append(d)

def par_str(tp,pp):
    if tp>1 and pp>1: return f"tp{tp}pp{pp}"
    if pp>1: return f"pp{pp}"
    if tp>1: return f"tp{tp}"
    return "tp1"

findings=[]; undet=[]; declared={}; seen={}
for tid,rn,tst,cfg,node,sa in tasks:
    cfg=json.loads(cfg); L=logs[tid]; R=res[rn]
    trunc=any(l.startswith("[sse]") for l in L)
    dec=None
    if cfg:
        dec=dict(src="tasks.task_config", gpu_count=cfg["gpu_count"], precision=cfg["precision"],
                 tp=cfg["tensor_parallel_size"], pp=cfg["pipeline_parallel_size"],
                 sweep=cfg["concurrency_sweep"], tokens=(cfg["input_tokens"],cfg["output_tokens"]), recipe=cfg.get("recipe"))
    else:
        d={}
        for l in L:
            m=re.match(r"\[bench\] recipe=(\S+)",l)
            if m: d["recipe"]=m.group(1)
            m=re.search(r"gpus=(\d+)",l)
            if m: d["gpu_count"]=int(m.group(1))
            m=re.match(r"\[bench\] concurrency sweep: ([\d ]+)",l)
            if m: d["sweep"]=[int(x) for x in m.group(1).split()]
            m=re.search(r"--tensor-parallel-size (\d+) --pipeline-parallel-size (\d+) --quantization (\S+) --max-model-len (\d+)",l)
            if m: d.update(tp=int(m.group(1)),pp=int(m.group(2)),precision=m.group(3),max_len=int(m.group(4)))
        if {"gpu_count","sweep","tp","pp","precision"} <= d.keys():
            dec=dict(src="task_logs launch preamble", **d)
    if dec is None:
        assert not cfg and trunc
        undet.append(rn); continue
    declared[rn]=dec
    defects=[]; ev=[]
    recv=lambda k: sorted({r[k] for r in R})
    # precision
    rp=recv("precision")
    if rp!=[dec["precision"]]:
        defects.append("defaulted_precision")
        ad=sorted({str(r["metrics"].get("actual_dtype")) for r in R if "actual_dtype" in r["metrics"]})
        ev.append(f"benchmark_results.precision={rp} but declared precision ({dec['src']})={dec['precision']}"+(f"; metrics.actual_dtype={ad}" if ad else "")+"; ingest default is 'fp16'")
    rg=recv("gpu_count")
    if rg!=[str(dec["gpu_count"])]:
        defects.append("defaulted_gpu_count")
        vd=sorted({str(r["metrics"].get("visible_devices")) for r in R if "visible_devices" in r["metrics"]})
        ev.append(f"benchmark_results.gpu_count={rg} but declared gpu_count ({dec['src']})={dec['gpu_count']}"+(f"; metrics.visible_devices={vd}" if vd else "")+"; ingest default is 1")
    rpar=recv("parallelism"); exp=par_str(dec["tp"],dec["pp"])
    if "" in rpar and (dec["tp"]>1 or dec["pp"]>1):
        defects.append("missing_parallelism")
        sv=sorted({r["metrics"].get("server_args","") for r in R}-{""})
        ev.append(f"benchmark_results.parallelism is NULL but declared tensor_parallel_size={dec['tp']}, pipeline_parallel_size={dec['pp']} ({dec['src']}) => {exp}; metrics has no 'parallelism' dict"+(f"; metrics.server_args={sv}" if sv else ""))
    elif rpar!=[exp]:
        print("WARN parallelism mismatch", rn, rpar, exp)
    zi=[r for r in R if r["input_tokens"]=="0" or r["output_tokens"]=="0"]
    if zi:
        defects.append("zero_token_config")
        rq=sorted({str(r["metrics"].get("request_params")) for r in zi if "request_params" in r["metrics"]})
        ev.append(f"{len(zi)}/{len(R)} result rows record input_tokens/output_tokens = 0; declared tokens ({dec['src']}) = "+(str(dec['tokens']) if 'tokens' in dec else f"max-model-len {dec.get('max_len')}")+(f"; metrics.request_params={rq}" if rq else ""))
    elif "tokens" in dec and (recv("input_tokens"),recv("output_tokens"))!=([str(dec["tokens"][0])],[str(dec["tokens"][1])]):
        print("WARN token mismatch", rn)
    elif "max_len" in dec and {int(r["input_tokens"])+int(r["output_tokens"]) for r in R}!={dec["max_len"]}:
        print("WARN max_len mismatch", rn)
    conc=sorted(int(r["concurrency"]) for r in R)
    missing=[c for c in dec["sweep"] if c not in conc]
    status_ok = recv("status")==["success"] and tst=="success"
    if missing and status_ok:
        defects.append("truncated_sweep")
        ev.append(f"declared concurrency_sweep ({dec['src']}) = {dec['sweep']}; benchmark_results has only {conc} (missing {missing}); recorded status 'success' (tasks.status={tst})")
    # status / pipeline / duration checks
    bad=[r["status"] for r in R if r["status"] not in ("success","failed")]
    if bad: defects.append("status_not_in_enum"); ev.append(f"status values {sorted(set(bad))}")
    if any(r["pipeline_version"]=="unknown" for r in R): defects.append("unknown_pipeline_version"); ev.append("pipeline_version='unknown'")
    if any(r["duration_seconds"]=="" or float(r["duration_seconds"])<=0 for r in R): defects.append("clock_skew_duration"); ev.append("duration_seconds null/non-positive")
    # duplicates: identical per-concurrency throughput vectors with same declared config
    sig=(R[0]["model_name"],R[0]["gpu_type"],dec["recipe"],tuple((r["concurrency"],r["total_token_throughput"]) for r in sorted(R,key=lambda r:int(r["concurrency"]))))
    if sig in seen:
        orig,onode,osa=seen[sig]
        defects.append("duplicate_logical_run")
        ev.append(f"re-execution of {orig}: same recipe {dec['recipe']}, same node {node} (original started {osa}, this one {sa}), and all {len(R)} total_token_throughput values identical at every concurrency")
    else: seen[sig]=(rn,node,sa)
    if defects: findings.append({"run_id":rn,"defects":defects,"evidence":" | ".join(ev)})
    declared[rn]["defects"]=defects
# also check for duplicates involving undeterminable runs (report only)
for rn in undet:
    R=res[rn]; v=tuple((r["concurrency"],r["total_token_throughput"]) for r in sorted(R,key=lambda r:int(r["concurrency"])))
    for s,(o,_,_) in seen.items():
        if s[3]==v: print("NOTE undet run",rn,"matches",o)
# leaderboard
groups=collections.defaultdict(list)
for rn,dec in declared.items():
    if dec["defects"]: continue
    R=res[rn]; conc={int(r["concurrency"]) for r in R}
    if not set(dec["sweep"])<=conc: continue
    r0=R[0]
    key=(r0["model_name"],r0["gpu_type"],r0["precision"],r0["parallelism"],int(r0["gpu_count"]),int(r0["input_tokens"]),int(r0["output_tokens"]))
    for k,i in (("model_name",0),("gpu_type",1),("precision",2),("parallelism",3)):
        assert len({r[k] for r in R})==1
    groups[key].append(max(float(r["total_token_throughput"]) for r in R))
entries=[]
for k,peaks in groups.items():
    t=max(peaks)
    entries.append(dict(model_name=k[0],gpu_type=k[1],precision=k[2],parallelism=k[3],gpu_count=k[4],input_tokens=k[5],output_tokens=k[6],
        total_token_throughput=t,per_gpu_throughput=round(t/k[4],2),runs_counted=len(peaks)))
bym=collections.defaultdict(list)
for e in entries: bym[e["model_name"]].append(e)
out=[]
for m in sorted(bym):
    es=sorted(bym[m],key=lambda e:(-e["per_gpu_throughput"],e["gpu_type"],e["precision"],e["parallelism"]))
    for i,e in enumerate(es,1): e["rank_within_model"]=i; out.append(e)
json.dump({"findings":findings,"undeterminable":undet},open("/app/audit/findings.json","w"),indent=2)
json.dump({"entries":out},open("/app/audit/leaderboard.json","w"),indent=2)
print(len(tasks),"runs;",len(findings),"findings;",len(undet),"undeterminable;",len(declared)-len(findings),"clean")
for f in findings: print(f["run_id"],f["defects"])
print("undet:",undet)
for e in out: print(e)
